import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";
import * as ui from "@e2e/ui-actions";
import { MANTLE_BASE_URL } from "@e2e/config";

const WELCOME_SKILL = "Session Start";
const ACTIVE_SKILL = "Card Disambiguation";
const CARD_REPLACE_MESSAGE = "I need to replace my lost credit card";
const CARD_PICK_MESSAGE = "Summit Rewards 6338";

test.describe("Mantle new-conversation reset", () => {
  test.use({ baseURL: MANTLE_BASE_URL });
  test.describe.configure({ timeout: 120_000 });

  test("Restarting the conversation clears the skill document and the grouped memory", async ({
    inspectorPage,
  }) => {
    await flows.mantle.activateCardDisambiguationRouting(inspectorPage, {
      expectedWelcomeSkill: WELCOME_SKILL,
      replaceMessage: CARD_REPLACE_MESSAGE,
      recoveryPickMessage: CARD_PICK_MESSAGE,
    });

    await test.step("Assert memory is populated under the active skill before the reset", async () => {
      await ui.viewMenu.actions(inspectorPage).switchToMemory();
      await ui.memoryPanel.assertions(inspectorPage).sectionIsVisible(ACTIVE_SKILL);
      await ui.memoryPanel.assertions(inspectorPage).entryCountAtLeast(1);
    });

    await test.step("Restart the conversation", async () => {
      await ui.inspectorShell.actions(inspectorPage).restartConversation();
    });

    await test.step("Assert the skill document resets to the welcome skill", async () => {
      // The previous skill (and its document) must not survive the restart; a fresh
      // session re-activates the welcome skill instead. The Memory view hides the
      // middle skill pane, so switch back to Active Flow first. skillHeaderShows
      // tolerates the brief no-active-skill window while the welcome turn runs.
      await ui.viewMenu.actions(inspectorPage).switchToActiveFlow();
      await ui.skillSection.assertions(inspectorPage).skillHeaderShows(WELCOME_SKILL);
    });

    await test.step("Assert the previous skill's memory section is gone", async () => {
      await ui.viewMenu.actions(inspectorPage).switchToMemory();
      await ui.memoryPanel.assertions(inspectorPage).sectionIsHidden(ACTIVE_SKILL);
    });
  });
});
